Harmonics

viewof freq2 = Inputs.range([50, 200], {value: 50, step: 1, label: "freq"})







harmonics = Array.from([0,1]).map(
  x =&gt; Array.from([1,2,3,4,5]).map(
    h =&gt; Object.create({
      x: x,
      y: freq2 * h,
      h: h
    })
  )
).flat()

Plot.plot({
  y: {
    label: "Frequency",
    domain: [0,1000]
  },
  color: {
    domain: [0,1000]
  },
  x: {
    label: "",
    ticks: []
  },
  marks: [
    Plot.lineY(
      harmonics,
      {
        x: "x",
        y: "y",
        stroke: "y",
        strokeWidth: 4
      },
    ),
    Plot.text(
      harmonics.filter(x =&gt; x.x &lt; 0.5),
      {
        x: 0.5,
        y: (d) =&gt; d.y+25,
        text: (d) =&gt; d.h-1,
        fill: "y",
        fontSize: 20
      }
    ),
    Plot.axisY({
      fontSize: 12
    })
  ]
})

